/**
 * Rôle : Classification d'un segment en "critique" ou "libre" selon la politique de sécurité financière (Section 5.5).
 * Entrées : Texte original, représentation protégée (Protected), et booléen optionnel indiquant si l'entrée du lexique est marquée critique.
 * Sorties : Booléen indiquant si le segment est critique (true) ou libre (false).
 * Limites : Un segment critique interdit formellement tout recours à un traducteur distant ou non validé.
 */

import type { Protected } from "./types.js";

/**
 * Liste configurable des mots-clés de sécurité, de conditions et d'opérations financières critiques (FR + EN).
 */
export const CRITICAL_KEYWORDS: readonly string[] = [
  // Français
  "code secret",
  "pin",
  "mot de passe",
  "ne partagez jamais",
  "arnaque",
  "fraude",
  "irréversible",
  "irreversible",
  "frais",
  "plafond",
  "limite",
  "conditions",
  "confirmer",
  "bénéficiaire",
  "beneficiaire",
  "solde",
  "total débité",
  "total debite",
  "activité inhabituelle",
  "activite inhabituelle",
  "vérifiez le bénéficiaire",
  "verifiez le beneficiaire",
  // Anglais
  "secret code",
  "password",
  "never share",
  "scam",
  "fraud",
  "irreversible",
  "cannot be undone",
  "fee",
  "fees",
  "daily limit",
  "limit",
  "terms",
  "conditions",
  "confirm",
  "beneficiary",
  "recipient",
  "balance",
  "total debited",
  "unusual activity",
  "verify the recipient",
  "check the recipient"
];

/**
 * Normalise une chaîne pour la recherche de mots-clés critiques.
 */
function normalizeForKeywordSearch(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\u00A0\u202F]/g, " ")
    .replace(/['’]/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Détermine si un segment est critique :
 * - Contient au moins un jeton protégé (montant, numéro, date, référence...) ;
 * - OU correspond à une entrée du lexique marquée critical: true ;
 * - OU contient un mot-clé de sécurité / condition financière.
 */
export function isCriticalSegment(
  originalText: string,
  protectedInput: Protected,
  lexiconMarkedCritical = false
): boolean {
  if (lexiconMarkedCritical) {
    return true;
  }

  if (protectedInput.tokens.length > 0) {
    return true;
  }

  const normalized = normalizeForKeywordSearch(originalText);
  for (const keyword of CRITICAL_KEYWORDS) {
    // Recherche par frontière de mot ou sous-chaîne d'expression
    const escaped = keyword.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const regex = new RegExp(`(?:^|[^a-zàâäæçéèêëîïôœùûüÿ])${escaped}(?:$|[^a-zàâäæçéèêëîïôœùûüÿ])`, "i");
    if (regex.test(normalized)) {
      return true;
    }
  }

  return false;
}

