/**
 * Rôle : Cache mémoire LRU (Least Recently Used) pour les traductions de textes protégés.
 * Entrées : Clé composée de (src, tgt, protectedText) contenant uniquement des jetons {{n}} et jamais de vraies valeurs sensibles.
 * Sorties : Chaîne traduite contenant les jetons {{n}}, ou undefined en cas d'absence.
 * Limites : Stockage exclusivement en mémoire vive (non persisté sur disque), taille bornée (2000 entrées par défaut).
 */

import type { LangCode } from "./types.js";

export class TranslationCache {
  private readonly maxEntries: number;
  private readonly store: Map<string, string>;

  constructor(maxEntries = 2000) {
    this.maxEntries = Math.max(1, maxEntries);
    this.store = new Map<string, string>();
  }

  /**
   * Construit une clé unique à partir de la langue source, de la langue cible et du texte protégé.
   */
  public static makeKey(src: LangCode, tgt: LangCode, protectedText: string): string {
    return `${src}::${tgt}::${protectedText}`;
  }

  /**
   * Récupère une entrée du cache et rafraîchit sa position LRU.
   */
  public get(src: LangCode, tgt: LangCode, protectedText: string): string | undefined {
    const key = TranslationCache.makeKey(src, tgt, protectedText);
    const val = this.store.get(key);
    if (val === undefined) {
      return undefined;
    }
    this.store.delete(key);
    this.store.set(key, val);
    return val;
  }

  /**
   * Enregistre une traduction de texte protégé dans le cache LRU.
   * Refuse par sécurité de mettre en cache si un texte non protégé suspect est détecté par erreur.
   */
  public set(src: LangCode, tgt: LangCode, protectedText: string, translatedWithTokens: string): void {
    const key = TranslationCache.makeKey(src, tgt, protectedText);
    if (this.store.has(key)) {
      this.store.delete(key);
    } else if (this.store.size >= this.maxEntries) {
      const oldestKey = this.store.keys().next().value;
      if (oldestKey !== undefined) {
        this.store.delete(oldestKey);
      }
    }
    this.store.set(key, translatedWithTokens);
  }

  /**
   * Vide intégralement le cache mémoire.
   */
  public clear(): void {
    this.store.clear();
  }

  /**
   * Retourne le nombre actuel d'entrées en cache.
   */
  public get size(): number {
    return this.store.size;
  }
}

