/**
 * Rôle : Vérification stricte de l'intégrité des informations financières et de la sûreté du texte après traduction.
 * Entrées : Texte source original, entrée protégée (Protected), sortie brute du fournisseur (avec jetons), et texte restauré final.
 * Sorties : Objet VerificationResult { valid: boolean, reason?: string }.
 * Limites : Si une seule règle échoue (jeton manquant/dupliqué/inventé, valeur sensible altérée, balise HTML injectée, texte vide ou longueur anormale), la traduction est rejetée ("failed-safe").
 */

import { protect } from "./protector.js";
import type { Protected } from "./types.js";

export interface VerificationResult {
  valid: boolean;
  reason?: string;
}

const TOKEN_EXTRACTOR_REGEX = /\{\{(\d+)\}\}|<x\s+id="(\d+)"\s*\/>/g;
const HTML_TAG_REGEX = /<\/?[a-zA-Z][^>]*>|[<>]/g;

const MIN_LENGTH_RATIO = 0.3;
const MAX_LENGTH_RATIO = 3.5;

/**
 * Extrait tous les numéros de jetons présents dans une chaîne traduite avant restauration.
 */
export function extractTokenIndices(translatedWithTokens: string): number[] {
  const indices: number[] = [];
  const regex = new RegExp(TOKEN_EXTRACTOR_REGEX.source, "g");
  let match: RegExpExecArray | null;

  while ((match = regex.exec(translatedWithTokens)) !== null) {
    const raw = match[1] ?? match[2];
    const num = Number.parseInt(raw, 10);
    if (!Number.isNaN(num)) {
      indices.push(num);
    }
  }
  return indices;
}

/**
 * Compare deux tableaux de chaînes comme des multi-ensembles (mêmes éléments avec les mêmes multiplicités).
 */
function areMultisetsEqual(a: string[], b: string[]): boolean {
  if (a.length !== b.length) {
    return false;
  }
  const sortedA = [...a].sort();
  const sortedB = [...b].sort();
  for (let i = 0; i < sortedA.length; i += 1) {
    if (sortedA[i] !== sortedB[i]) {
      return false;
    }
  }
  return true;
}

/**
 * Exécute les 4 contrôles d'intégrité obligatoires (Section 5.6) :
 * 1. Conservation bijective des jetons {{n}} (ni perdus, ni dupliqués, ni inventés).
 * 2. Égalité en multi-ensemble des valeurs sensibles ré-extraites sur le texte restauré.
 * 3. Sortie non vide et absence de balises HTML (< >) absentes de l'entrée.
 * 4. Ratio de longueur compris entre 0.3 et 3.5.
 */
export function verifyTranslation(
  originalText: string,
  protectedInput: Protected,
  translatedWithTokens: string,
  restoredOutput: string
): VerificationResult {
  // 3a. Vérification de sortie non vide
  if (!restoredOutput || restoredOutput.trim().length === 0) {
    return { valid: false, reason: "empty-output" };
  }

  // 1. Vérification des jetons {{n}} dans la sortie du traducteur (avant restauration)
  const expectedCount = protectedInput.tokens.length;
  const foundIndices = extractTokenIndices(translatedWithTokens);

  if (foundIndices.length !== expectedCount) {
    return { valid: false, reason: "token-mismatch" };
  }

  const seen = new Set<number>();
  for (const idx of foundIndices) {
    if (idx < 1 || idx > expectedCount || seen.has(idx)) {
      return { valid: false, reason: "token-mismatch" };
    }
    seen.add(idx);
  }

  // Vérifier qu'aucun jeton non résolu ne subsiste dans le texte restauré (sauf s'il était dans l'original)
  const unresolvedInRestored = extractTokenIndices(restoredOutput);
  const originalTokensInSource = extractTokenIndices(originalText);
  if (unresolvedInRestored.length > originalTokensInSource.length) {
    return { valid: false, reason: "unresolved-token" };
  }

  // 3b. Vérification d'absence de balises ou chevrons HTML injectés
  const sourceHtmlMatches: string[] = originalText.match(HTML_TAG_REGEX) ?? [];
  const outputHtmlMatches: string[] = restoredOutput.match(HTML_TAG_REGEX) ?? [];
  if (outputHtmlMatches.length > sourceHtmlMatches.length) {
    return { valid: false, reason: "unexpected-html" };
  }
  for (const tag of outputHtmlMatches) {
    if (!sourceHtmlMatches.includes(tag)) {
      return { valid: false, reason: "unexpected-html" };
    }
  }

  // 2. Ré-extraction des valeurs sensibles sur le texte final restauré (multi-ensemble identique)
  const reprotected = protect(restoredOutput);
  if (!areMultisetsEqual(protectedInput.tokens, reprotected.tokens)) {
    return { valid: false, reason: "sensitive-value-mismatch" };
  }

  // 4. Vérification du ratio de longueur raisonnable (0.3 à 3.5 pour les phrases >= 10 caractères ; souple sur les abréviations courtes ex. "ID" -> "Identifiant")
  const srcLen = originalText.trim().length;
  const outLen = restoredOutput.trim().length;
  if (srcLen >= 10) {
    const ratio = outLen / srcLen;
    if (ratio < MIN_LENGTH_RATIO || ratio > MAX_LENGTH_RATIO) {
      return { valid: false, reason: "suspicious-length-ratio" };
    }
  } else if (srcLen > 0 && outLen > Math.max(40, srcLen * 8)) {
    return { valid: false, reason: "suspicious-length-ratio" };
  }

  return { valid: true };
}
