/**
 * Rôle : Fournisseur de traduction déterministe et hors-ligne basé sur le lexique et les gabarits validés.
 * Entrées : Objet Protected { text, tokens }, langue source, langue cible et contexte { critical }.
 * Sorties : Chaîne traduite (avec jetons {{n}} et valeurs de slots préservés) ou null si aucune entrée ne correspond.
 * Limites : Ne tente jamais de traduction mot à mot (interdit pour éviter tout contresens financier).
 */

import {
  buildCompiledLexicon,
  getDefaultLexicon,
  normalizeLexiconText,
  type CompiledLexicon
} from "../../lexicon/loader.js";
import type {
  LangCode,
  LanguageInfo,
  LexiconEntry,
  Protected,
  TranslationProvider
} from "../types.js";

export interface LexiconMatchDetail {
  output: string;
  entry: LexiconEntry;
  ambiguousTie?: boolean;
}

export class LexiconProvider implements TranslationProvider {
  public readonly id = "lexicon";
  private readonly compiled: CompiledLexicon;
  private readonly onDebugTie?: (firstId: string, secondId: string) => void;

  constructor(
    customEntries?: LexiconEntry[],
    customLanguages?: LanguageInfo[],
    onDebugTie?: (firstId: string, secondId: string) => void
  ) {
    this.compiled =
      customEntries || customLanguages
        ? buildCompiledLexicon(customEntries, customLanguages)
        : getDefaultLexicon();
    this.onDebugTie = onDebugTie;
  }

  /**
   * Vérifie si la paire de langues est prise en charge par le lexique.
   */
  public canTranslate(src: LangCode, tgt: LangCode): boolean {
    if (src === tgt) {
      return false;
    }
    const hasSrc =
      this.compiled.exactMap.has(src) || this.compiled.templatesByLang.has(src);
    const hasTgt = this.compiled.entries.some((e) => Boolean(e.text[tgt]));
    return hasSrc && hasTgt;
  }

  /**
   * Recherche une correspondance (exacte puis par gabarit) et retourne les détails de l'entrée trouvée.
   */
  public matchWithDetails(
    inputText: string,
    src: LangCode,
    tgt: LangCode
  ): LexiconMatchDetail | null {
    if (!inputText || src === tgt) {
      return null;
    }

    // Étape 1 : Correspondance EXACTE sur les entrées sans slot
    const normalizedInput = normalizeLexiconText(inputText);
    const langExactMap = this.compiled.exactMap.get(src);
    if (langExactMap) {
      const candidates = langExactMap.get(normalizedInput);
      if (candidates && candidates.length > 0) {
        const usable = candidates.filter((e) => this.isEntryUsableForTarget(e, tgt));
        if (usable.length > 0) {
          if (usable.length > 1 && this.onDebugTie) {
            this.onDebugTie(usable[0].id, usable[1].id);
          }
          const chosen = usable[0];
          return {
            output: chosen.text[tgt],
            entry: chosen,
            ambiguousTie: usable.length > 1
          };
        }
      }
    }

    // Étape 2 : Correspondance par GABARIT (déjà triés par literalLength décroissante)
    const templates = this.compiled.templatesByLang.get(src);
    if (!templates || templates.length === 0) {
      return null;
    }

    const trimmedInput = inputText.trim();
    const matchingTemplates: Array<{
      entry: LexiconEntry;
      rendered: string;
      literalLength: number;
    }> = [];

    for (const tpl of templates) {
      if (!this.isEntryUsableForTarget(tpl.entry, tgt)) {
        continue;
      }
      const match = tpl.regex.exec(trimmedInput);
      if (!match) {
        continue;
      }

      const slotValues: Record<string, string> = {};
      let validSlots = true;
      for (let i = 0; i < tpl.slotNames.length; i += 1) {
        const slotName = tpl.slotNames[i];
        const captured = match[i + 1]?.trim() ?? "";
        if (captured.length === 0) {
          validSlots = false;
          break;
        }
        // Si un même slot apparaît plusieurs fois dans le gabarit source, ses valeurs doivent coïncider
        if (slotValues[slotName] !== undefined && slotValues[slotName] !== captured) {
          validSlots = false;
          break;
        }
        slotValues[slotName] = captured;
      }

      if (!validSlots) {
        continue;
      }

      const targetTemplate = tpl.entry.text[tgt];
      const rendered = targetTemplate.replace(/\{([a-zA-Z0-9_]+)\}/g, (full, slotName: string) => {
        return slotValues[slotName] !== undefined ? slotValues[slotName] : full;
      });

      matchingTemplates.push({
        entry: tpl.entry,
        rendered,
        literalLength: tpl.literalLength
      });
    }

    if (matchingTemplates.length === 0) {
      return null;
    }

    const best = matchingTemplates[0];
    const tie =
      matchingTemplates.length > 1 &&
      matchingTemplates[1].literalLength === best.literalLength;

    if (tie && this.onDebugTie) {
      this.onDebugTie(best.entry.id, matchingTemplates[1].entry.id);
    }

    return {
      output: best.rendered,
      entry: best.entry,
      ambiguousTie: tie
    };
  }

  /**
   * Implémentation de TranslationProvider.translate().
   */
  public async translate(
    input: Protected,
    src: LangCode,
    tgt: LangCode,
    _ctx: { critical: boolean }
  ): Promise<string | null> {
    const matched = this.matchWithDetails(input.text, src, tgt);
    return matched ? matched.output : null;
  }

  /**
   * Indique si un texte correspond à une entrée marquée critical: true dans la langue source.
   */
  public isLexiconCritical(inputText: string, src: LangCode): boolean {
    const normalizedInput = normalizeLexiconText(inputText);
    const exactCandidates = this.compiled.exactMap.get(src)?.get(normalizedInput);
    if (exactCandidates?.some((e) => e.critical)) {
      return true;
    }
    const templates = this.compiled.templatesByLang.get(src) ?? [];
    const trimmed = inputText.trim();
    for (const tpl of templates) {
      if (tpl.entry.critical && tpl.regex.test(trimmed)) {
        return true;
      }
    }
    return false;
  }

  /**
   * Vérifie si un texte court (ex. bouton "Valider", "Connexion") existe exactement dans une langue du lexique.
   */
  public hasExactEntryInLang(inputText: string, lang: LangCode): boolean {
    const normalized = normalizeLexiconText(inputText);
    const list = this.compiled.exactMap.get(lang)?.get(normalized);
    return Boolean(list && list.length > 0);
  }

  /**
   * Retourne la liste des langues déclarées dans languages.json qui possèdent au moins une entrée dans lexicon.json.
   */
  public getAvailableLanguages(): LanguageInfo[] {
    return this.compiled.languages.filter((langInfo) =>
      this.compiled.entries.some((entry) => Boolean(entry.text[langInfo.code]))
    );
  }

  private isEntryUsableForTarget(entry: LexiconEntry, tgt: LangCode): boolean {
    const targetText = entry.text[tgt];
    if (!targetText || targetText.trim().length === 0) {
      return false;
    }
    // Si la langue cible est déclarée "validated" dans languages.json et que l'entrée est critique,
    // son statut propre pour cette langue doit être "validated".
    const langInfo = this.compiled.languages.find((l) => l.code === tgt);
    if (entry.critical && langInfo?.status === "validated") {
      const entryStatus = entry.status?.[tgt];
      if (entryStatus !== "validated") {
        return false;
      }
    }
    return true;
  }
}

