/**
 * Rôle : Contrôleur de l'interface popup (Section 5.9).
 * Entrées : État de l'onglet actif (GET_STATUS via browser.tabs.sendMessage), réglages (browser.storage.local) et interactions utilisateur.
 * Sorties : Mise à jour des réglages, bascule Original/Traduit, retraduction et mini-traducteur rapide (avec détection de la Web Speech API).
 * Limites : S'adapte automatiquement en FR ou EN selon browser.i18n.getUILanguage() et affiche un message d'aide clair si le content script ne répond pas.
 */

import { detect, detectWithShortWords } from "../core/detector.js";
import { TranslationEngine } from "../core/engine.js";
import { RemoteProvider } from "../core/providers/remote-provider.js";
import type { LangCode, LanguageValidationStatus } from "../core/types.js";
import { browser } from "../shared/ext.js";
import type { ContentStatusResponse } from "../shared/messages.js";
import {
  getSettings,
  isHostEnabled,
  updateSettings,
  type Settings
} from "../shared/settings.js";

